events {
    worker_connections 4096;  # 4 worker x 4096 = 16384 koneksi simultan
    use epoll;                # event method tercepat di Linux
    multi_accept on;          # terima banyak koneksi sekaligus
}

http {
    # Koneksi client -> NGINX
    keepalive_timeout 65s;      # tutup koneksi yang menganggur > 65 detik
    keepalive_requests 100;     # maks 100 request per koneksi, lalu tutup

    # Koneksi NGINX -> upstream (hemat koneksi ke backend)
    upstream app_backend {
        server 127.0.0.1:3000;
        keepalive 32;           # simpan 32 koneksi idle per worker
    }
}

http {
    client_header_timeout 10s;   # header harus lengkap dalam 10 detik
    client_body_timeout 10s;     # body (upload) harus selesai dalam 10 detik
    send_timeout 10s;            # client harus membaca response dalam 10 detik

    # Upload besar butuh body timeout lebih longgar:
    # location /upload/ {
    #     client_body_timeout 300s;
    #     client_max_body_size 100m;
    # }
}

location /api/ {
    proxy_pass http://app_backend;

    proxy_connect_timeout 5s;    # upstream harus menjawab TCP dalam 5 detik
    proxy_send_timeout 10s;      # kirim request ke upstream maks 10 detik
    proxy_read_timeout 30s;      # tunggu response upstream maks 30 detik

    # Endpoint berat (laporan/export) boleh lebih lama:
    # location /api/reports/ {
    #     proxy_read_timeout 300s;
    # }
}

location /api/ {
    proxy_pass http://app_backend;
    proxy_next_upstream error timeout http_500 http_502 http_503;
    proxy_next_upstream_timeout 10s;   # total percobaan maks 10 detik
    proxy_next_upstream_tries 2;       # maks 2 kali percobaan
    resolver_timeout 5s;               # DNS upstream maks 5 detik
    lingering_timeout 5s;
    reset_timedout_connection on;      # reset socket yang timeout
}

location /api/products/ {
    proxy_pass http://app_backend;
    proxy_cache api_cache;
    proxy_cache_valid 200 302 10m;   # response sukses: cache 10 menit
    proxy_cache_valid 404 1m;        # not found: cache 1 menit saja
    proxy_cache_key "$scheme$request_method$host$request_uri";
    add_header X-Cache-Status $upstream_cache_status;  # HIT / MISS / BYPASS
}

# Jangan cache untuk user yang login (punya cookie sesi)
location /api/ {
    proxy_pass http://app_backend;
    proxy_cache api_cache;
    proxy_cache_bypass $cookie_session $http_authorization;
    proxy_no_cache $cookie_session $http_authorization;
    # $cookie_session dan $http_authorization kosong untuk user anonim
    # -> response mereka di-cache; user login selalu dapat data segar
    add_header X-Cache-Status $upstream_cache_status;
}

# Request masuk: GET /api/users/42

location /api/ {
    proxy_pass http://127.0.0.1:3000;
    # Diteruskan apa adanya: GET http://127.0.0.1:3000/api/users/42
}

location /api/ {
    proxy_pass http://127.0.0.1:3000/;
    # "/api/" diganti "/": GET http://127.0.0.1:3000/users/42
}

location /api/ {
    proxy_pass http://app_backend;
    proxy_set_header Host $host;                    # domain asli (api.example.id)
    proxy_set_header X-Real-IP $remote_addr;        # IP asli client
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;     # http / https
    # Tanpa X-Forwarded-Proto, aplikasi mengira request lewat HTTP
    # dan bisa redirect loop http -> https tanpa henti.
}

upstream app_backend {
    least_conn;  # kirim ke server dengan koneksi aktif paling sedikit
    server 10.0.0.11:3000 max_fails=3 fail_timeout=30s;
    server 10.0.0.12:3000 max_fails=3 fail_timeout=30s;
    server 10.0.0.13:3000 backup;   # hanya dipakai kalau dua server utama mati
    keepalive 32;                    # koneksi idle ke upstream per worker
}
# least_conn bagus untuk request yang durasinya bervariasi.
# Alternatif: ip_hash (sesi menempel ke satu server) atau round_robin (default).

location /api/ {
    proxy_pass http://app_backend;
    proxy_http_version 1.1;
    proxy_set_header Connection "";   # aktifkan keep-alive ke upstream

    # WebSocket: naikkan koneksi HTTP menjadi WebSocket
    # location /ws/ {
    #     proxy_pass http://app_backend;
    #     proxy_http_version 1.1;
    #     proxy_set_header Upgrade $http_upgrade;
    #     proxy_set_header Connection "upgrade";
    #     proxy_read_timeout 86400;   # WebSocket hidup lama
    # }

    # SSE / streaming: matikan buffering agar event mengalir langsung
    # proxy_buffering off;
    # proxy_cache off;
}

upstream app_backend {
    least_conn;
    server 127.0.0.1:3000 max_fails=3 fail_timeout=30s;
    server 127.0.0.1:3001 max_fails=3 fail_timeout=30s;
    keepalive 32;
}

server {
    listen 443 ssl http2;
    server_name api.example.id;

    ssl_certificate     /etc/letsencrypt/live/api.example.id/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/api.example.id/privkey.pem;

    # Timeout: ketat untuk API normal
    client_body_timeout 10s;
    send_timeout 10s;

    # Cache untuk endpoint read-only yang ramai
    location /api/products/ {
        proxy_pass http://app_backend;
        proxy_cache api_cache;
        proxy_cache_valid 200 10m;
        add_header X-Cache-Status $upstream_cache_status;
        proxy_read_timeout 30s;
    }

    # API umum: tanpa cache, dengan header lengkap
    location /api/ {
        proxy_pass http://app_backend;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Connection "";
        proxy_connect_timeout 5s;
        proxy_read_timeout 30s;
    }

    # Endpoint berat: timeout lebih longgar
    location /api/reports/ {
        proxy_pass http://app_backend;
        proxy_read_timeout 300s;
    }
}
